  'Research Methods in Social Work',
  'Research Methods in Social Work',
  'Students learn why social work research exists: to improve services, test assumptions, honor client knowledge, and make practice accountable to evidence and justice. They turn practice problems into researchable questions grounded in scholarship, theory, and lived experience; study ethics, IRB review, anti-oppressive research, and community accountability; match designs to claims about needs, experiences, programs, outcomes, and causal change; and cover sampling, culturally responsive measurement, surveys, quantitative and qualitative analysis, mixed and community-engaged inquiry, evidence appraisal, practice and program evaluation, research communication, and an applied research or evaluation proposal.',
  $rmswjson${"slug": "research-methods-in-social-work", "title": "Research Methods in Social Work", "description": "Students learn why social work research exists: to improve services, test assumptions, honor client knowledge, and make practice accountable to evidence and justice. They turn practice problems into researchable questions grounded in scholarship, theory, and lived experience; study ethics, IRB review, anti-oppressive research, and community accountability; match designs to claims about needs, experiences, programs, outcomes, and causal change; and cover sampling, culturally responsive measurement, surveys, quantitative and qualitative analysis, mixed and community-engaged inquiry, evidence appraisal, practice and program evaluation, research communication, and an applied research or evaluation proposal.", "topics": [{"id": "a52fd5bd-884b-4383-8e7f-6304a847ab2e", "type": "topic", "title": "Social Work Inquiry, Evidence-Informed Practice, and Practice Wisdom", "description": "Students learn why social work research exists: to improve services, test assumptions, honor client knowledge, and make practice accountable to evidence and justice.", "children": [{"id": "5e2504dd-664d-487e-a723-5427a4502b56", "type": "subtopic", "title": "Why research matters in social work", "children": [{"id": "26d28558-3dfb-4d58-8445-cfb0b6866000", "type": "concept", "title": "Improving services and outcomes"}, {"id": "187305e8-b965-4c06-8355-aebeafd33f04", "type": "concept", "title": "Testing assumptions and common practices"}, {"id": "4bd42d99-8552-4cb2-9c1e-30012024b880", "type": "concept", "title": "Accountability to clients, agencies, funders, and communities"}, {"id": "de2097c8-2e8f-4a6f-a6b6-ff3a62b21406", "type": "concept", "title": "Research as a tool for social justice"}], "description": "Students begin by seeing research as a practice responsibility, not a detached academic exercise."}, {"id": "825c57ef-daf8-4a42-aaaa-5dabfe14aef8", "type": "subtopic", "title": "Evidence-informed practice and practice wisdom", "children": [{"id": "7f69b830-1ec6-4eaf-87c3-5da2b8119926", "type": "concept", "title": "Evidence-based versus evidence-informed practice"}, {"id": "9ef9cb69-54a6-416d-b1ff-622e1ebdc11b", "type": "concept", "title": "Client voice and shared decision-making"}, {"id": "b89872b5-fede-4ca2-8215-37b1da547aa1", "type": "concept", "title": "Practice wisdom and reflective judgment"}, {"id": "3f6b6ed8-c88c-4955-89a1-2f69897d84b1", "type": "concept", "title": "Limits of evidence hierarchies"}], "description": "This subtopic balances formal research evidence with practitioner expertise, client preferences, and community context."}, {"id": "086676cf-79d6-4c2f-b976-9407760ca6f3", "type": "subtopic", "title": "Person-in-environment as research lens", "children": [{"id": "55b06b59-9d00-4da4-aa85-9ad34250e451", "type": "concept", "title": "Micro, mezzo, and macro levels"}, {"id": "131da822-88fd-4226-83c1-e01d11527ea1", "type": "concept", "title": "Social determinants and structural inequity"}, {"id": "3a4f8cdb-66f2-4e44-ac5d-bf39ad311a4a", "type": "concept", "title": "Strengths, risk, and protective factors"}, {"id": "ac25d59e-b998-4fc3-85e7-98fe61ea9ccb", "type": "concept", "title": "Contextualizing individual outcomes"}], "description": "Students learn to frame research questions around people, relationships, institutions, policies, and structural conditions."}]}, {"id": "4575085e-4741-4011-a0a2-6024055b53ed", "type": "topic", "title": "Research Questions, Literature Reviews, and Conceptual Frameworks", "description": "This topic teaches students to turn practice problems into researchable questions grounded in scholarship, theory, and lived experience.", "children": [{"id": "6e3de614-48e4-49f8-a9fa-d792fd2621ee", "type": "subtopic", "title": "Formulating researchable questions", "children": [{"id": "771d0a34-d8bc-474d-abc7-2e5d4e4eac6e", "type": "concept", "title": "Descriptive, exploratory, explanatory, evaluative, and causal questions"}, {"id": "c1dc5d14-d10a-454d-921d-fbf34561698b", "type": "concept", "title": "Population, setting, intervention, comparison, and outcome framing"}, {"id": "bc4f0593-5695-436e-a9b4-91d09070b3c5", "type": "concept", "title": "Feasibility and significance"}, {"id": "3b989b67-e821-48d5-b7da-a801d2b8cb8f", "type": "concept", "title": "Equity and community relevance"}], "description": "The point is to turn broad practice concerns into focused questions that can guide evidence gathering."}, {"id": "9608b2c2-59bf-44d2-aa62-f739be1192dd", "type": "subtopic", "title": "Literature strategy", "children": [{"id": "6eb02970-faa0-46dc-9e6c-223de69d3fce", "type": "concept", "title": "Databases and search terms"}, {"id": "2520277a-c907-4e33-a6f3-5e0163c7d04d", "type": "concept", "title": "Citation chaining and source evaluation"}, {"id": "6f325598-81da-4b7a-84c1-b1a2a5f71f08", "type": "concept", "title": "Annotated bibliography methods"}, {"id": "bb45a267-162f-4925-8fb5-daf6b4c9715b", "type": "concept", "title": "Synthesizing themes, gaps, and debates"}], "description": "Students learn to locate and synthesize scholarship rather than simply collect sources."}, {"id": "73469351-7549-48b8-9c19-ab5af53200bb", "type": "subtopic", "title": "Conceptual and theoretical frameworks", "children": [{"id": "e53274cc-26f8-42ea-a086-ffb97714bcc2", "type": "concept", "title": "Ecological systems and person-in-environment theory"}, {"id": "642c66ea-b014-4803-9c6f-da4577eba3b8", "type": "concept", "title": "Critical, feminist, anti-oppressive, and strengths-based frameworks"}, {"id": "411afa34-e430-4ceb-92e8-fe39c3705935", "type": "concept", "title": "Logic models and mechanisms"}, {"id": "e738b066-5042-4d97-b2cd-7dcb40d2dc1d", "type": "concept", "title": "Hypotheses, propositions, and assumptions"}], "description": "Frameworks help students explain why variables, experiences, systems, or interventions may be connected."}]}, {"id": "861c2a9b-9fa6-4a56-81e3-28f177388120", "type": "topic", "title": "Ethics, IRB, Anti-Oppressive Research, and Community Accountability", "description": "Students study the ethical responsibilities of research with people, communities, agencies, and vulnerable populations.", "children": [{"id": "2aee77aa-7b86-4680-bb4d-dc42d2f70c98", "type": "subtopic", "title": "Human-subjects ethics", "children": [{"id": "e7758fd5-a8d7-41b1-b0af-79aebcede7c9", "type": "concept", "title": "Informed consent and assent"}, {"id": "7a1abea8-9591-43e0-a34f-a4280f17cb82", "type": "concept", "title": "Risk, benefit, privacy, and confidentiality"}, {"id": "2d6e604c-991d-493f-b22b-c118c24edace", "type": "concept", "title": "Deception, coercion, and incentives"}, {"id": "7bf5dfe7-8748-4a2f-8592-bcdd7e7ba695", "type": "concept", "title": "Mandated reporting and safety limits"}], "description": "Students learn the obligations that protect participants before, during, and after a study."}, {"id": "d73262f7-a032-41a9-bdab-358ee197b32a", "type": "subtopic", "title": "IRB and research governance", "children": [{"id": "e74bac55-3d89-4f74-b2f6-cb746d074da3", "type": "concept", "title": "Exempt, expedited, and full-board review"}, {"id": "db2adb47-ed9c-4aed-a0bc-0706f14107f2", "type": "concept", "title": "Recruitment materials and consent forms"}, {"id": "c126f0f1-66c6-4d94-9db5-ce7bcff09bd4", "type": "concept", "title": "Data security and retention"}, {"id": "0a262967-1308-4ac8-bffc-3c202a5d7536", "type": "concept", "title": "Adverse events and protocol amendments"}], "description": "This subtopic demystifies institutional review without reducing ethics to paperwork."}, {"id": "712b2468-c4f5-40b4-afbb-fad74b170393", "type": "subtopic", "title": "Anti-oppressive and accountable research", "children": [{"id": "8eb772ad-42a0-488b-a08a-2ce56aec7bf9", "type": "concept", "title": "Research with marginalized and vulnerable populations"}, {"id": "2a996d0c-ba3b-4d4d-806a-56fef373ae47", "type": "concept", "title": "Power, extraction, tokenism, and reciprocity"}, {"id": "76206327-b17c-4be4-85f3-b71e617ebdc7", "type": "concept", "title": "Community advisory roles"}, {"id": "f701c18c-4fe3-4d75-8187-cf0cae0b9e78", "type": "concept", "title": "Culturally responsive and trauma-informed data collection"}], "description": "Students examine how research can reproduce harm or support liberation depending on design and relationship."}]}, {"id": "0e4cd910-678b-420d-81e9-18e51661c550", "type": "topic", "title": "Research Design: Descriptive, Exploratory, Explanatory, Experimental, and Evaluation Logic", "description": "Students learn how different designs support different claims about needs, experiences, programs, outcomes, and causal change.", "children": [{"id": "bee98d54-2e19-4098-922b-fb7a0dbc823b", "type": "subtopic", "title": "Design alignment", "children": [{"id": "7356bdac-9901-4d43-af9c-72482f6d6bd1", "type": "concept", "title": "Research design matrix"}, {"id": "458ae94d-3bf8-4f07-8ca6-e75b33c765e1", "type": "concept", "title": "Unit of analysis and unit of observation"}, {"id": "a68fadcb-638b-412c-9635-036d6497533e", "type": "concept", "title": "Cross-sectional and longitudinal designs"}, {"id": "31919ce6-aa05-4a2b-b658-96acad3af858", "type": "concept", "title": "Threats to validity and credibility"}], "description": "Students learn to match question, evidence, method, sample, and claim."}, {"id": "55c0a36b-56be-45a0-b5c9-c1e5831495db", "type": "subtopic", "title": "Quantitative, qualitative, and causal design families", "children": [{"id": "44e93995-c771-4a3c-ac0b-2b2ada5df33b", "type": "concept", "title": "Descriptive surveys and administrative data studies"}, {"id": "0d24cddc-21ee-41f2-b42f-ea855b252f06", "type": "concept", "title": "Qualitative interview, focus group, observation, and case designs"}, {"id": "af5fea8c-f3c5-4330-854d-753ceffd93c7", "type": "concept", "title": "Experimental and quasi-experimental designs"}, {"id": "0015d35b-857d-4d07-be0b-615a2981bb6e", "type": "concept", "title": "Causal language and limits"}], "description": "This subtopic clarifies what different designs can and cannot prove."}, {"id": "87be6126-dfe5-4f21-ba91-347ddcd69318", "type": "subtopic", "title": "Evaluation logic", "children": [{"id": "a4e7242f-ae06-4fc4-8ec8-d3afa207337d", "type": "concept", "title": "Needs, process, outcome, and impact questions"}, {"id": "27cd9fea-c397-4f6b-b1b4-3bd986e65974", "type": "concept", "title": "Implementation and fidelity"}, {"id": "0542f9e3-34b5-438b-a83e-5ceed4e009e0", "type": "concept", "title": "Utilization and improvement"}, {"id": "a705ae09-cc84-407d-a61c-57993a17658d", "type": "concept", "title": "Stakeholder decision needs"}], "description": "Students learn how evaluation designs answer practical questions about programs and services."}]}, {"id": "4ff55db1-90d0-4818-a63f-31dcad0cea3a", "type": "topic", "title": "Sampling, Recruitment, Access, and Representation", "description": "This topic covers how researchers identify participants, settings, records, and communities while managing feasibility, trust, bias, and equity.", "children": [{"id": "1cde3fd9-40db-49f8-bc32-f900b7cb8305", "type": "subtopic", "title": "Sampling concepts", "children": [{"id": "491ff1c4-a2fd-4ce7-bbc1-c5cbdf439ad1", "type": "concept", "title": "Population, sample, frame, eligibility, and cases"}, {"id": "3343d597-74d7-47dc-858a-551afc95f8f3", "type": "concept", "title": "Probability and nonprobability sampling"}, {"id": "5dfcad97-035d-46ad-9533-001053159f89", "type": "concept", "title": "Purposive, snowball, convenience, stratified, and cluster approaches"}, {"id": "e6b3f04b-e4fc-4d04-822f-20abd53d5c8d", "type": "concept", "title": "Representativeness, saturation, and information power"}], "description": "Sampling shapes whose experiences count and how far findings can travel."}, {"id": "a86d5e6d-124a-4255-88f6-1238133d779f", "type": "subtopic", "title": "Recruitment and field access", "children": [{"id": "0c7f558f-04e9-4561-aa67-f57c7badc986", "type": "concept", "title": "Gatekeepers and agency permissions"}, {"id": "e30a6c51-ce5d-4c24-be53-d173cff7dc69", "type": "concept", "title": "Incentives and participation barriers"}, {"id": "f81f31cb-2104-46e2-baef-bdf1c18edcad", "type": "concept", "title": "Language access and disability access"}, {"id": "0ef2bd0f-4219-4f73-819e-678475912b40", "type": "concept", "title": "Trust, transparency, and refusal"}], "description": "Students prepare for the practical work of gaining ethical, respectful access."}, {"id": "f43d1496-dd99-4f06-83f7-dcc0a63dcda8", "type": "subtopic", "title": "Bias, equity, and missing voices", "children": [{"id": "ae8a74ee-0dae-429b-bb5c-8968f5f4f791", "type": "concept", "title": "Selection bias and nonresponse"}, {"id": "37183aed-508f-4e73-aaa9-49b34a578f4e", "type": "concept", "title": "Hard-to-reach populations"}, {"id": "0a564248-8fd2-492b-aaa6-d237dccc3425", "type": "concept", "title": "Attrition and retention"}, {"id": "00808d62-92b5-457a-a1aa-bf6b6a879fa0", "type": "concept", "title": "Oversampling and subgroup analysis"}], "description": "The goal is to notice whose data is missing and why."}]}, {"id": "17e26149-46ff-4f13-831f-1dde7107105d", "type": "topic", "title": "Measurement, Operationalization, Reliability, Validity, and Cultural Responsiveness", "description": "Students learn how concepts become measures and how measurement choices can help or harm practice knowledge.", "children": [{"id": "5c45c675-7537-4a32-8e82-faa2abf1ccc9", "type": "subtopic", "title": "Conceptualization and operationalization", "children": [{"id": "d5e6dc17-a9a5-4da2-9b26-a91d658a4624", "type": "concept", "title": "Wellbeing, safety, housing stability, resilience, engagement, stigma, functioning, and social support"}, {"id": "59fb2f48-813b-4022-9a3f-8f8877524edb", "type": "concept", "title": "Variables, constructs, dimensions, and indicators"}, {"id": "366bc990-3fef-435f-9ed5-e3f4a581d749", "type": "concept", "title": "Administrative records and standardized scales"}, {"id": "c8b24477-b7d8-427c-bb08-69d7f7605f82", "type": "concept", "title": "Practice-defined outcomes"}], "description": "Students learn how abstract social work concepts become observable indicators."}, {"id": "ad28c670-341f-48b8-87a6-1486a97ab6ec", "type": "subtopic", "title": "Reliability and validity", "children": [{"id": "a17f0ba8-9941-4bd6-9954-348487c0ca8d", "type": "concept", "title": "Test-retest and internal consistency"}, {"id": "a0806931-6ba2-420d-8498-1cc1f778a8c9", "type": "concept", "title": "Interrater and intercoder reliability"}, {"id": "221a250f-2fe4-4e9c-84f6-7c659d086279", "type": "concept", "title": "Face, content, criterion, and construct validity"}, {"id": "e7c3848f-e018-487d-8042-3d9f20250bc6", "type": "concept", "title": "Sensitivity, specificity, and screening limits"}], "description": "Students evaluate whether measures are consistent, meaningful, and appropriate."}, {"id": "6bcf4f01-497b-4564-96e4-9c5cacaa3b55", "type": "subtopic", "title": "Culturally responsive measurement", "children": [{"id": "c835d018-f1a5-4727-9928-15b52c7228b1", "type": "concept", "title": "Measurement equivalence"}, {"id": "41ae41b7-af9d-4eb8-99eb-4d06c35cbb63", "type": "concept", "title": "Translation and adaptation"}, {"id": "b5f9cdc7-bc58-4025-bdb9-c30923a41a33", "type": "concept", "title": "Community of instruments"}, {"id": "53559e4e-c706-4250-a905-6c862491cb37", "type": "concept", "title": "Avoiding deficit-only indicators"}], "description": "Measures can misrepresent communities when they ignore language, culture, power, or context."}]}, {"id": "e9ac340b-2d20-49e8-8034-c6a87c2295d7", "type": "topic", "title": "Survey Research and Data Collection Instruments", "description": "Students design and critique surveys, questionnaires, screeners, interview protocols, and agency data forms.", "children": [{"id": "a5e24552-c63a-42b3-82fc-092e3ed2b17d", "type": "subtopic", "title": "Survey design", "children": [{"id": "6b060489-acba-4025-9f35-0d00c272ce7c", "type": "concept", "title": "Survey modes: online, phone, mail, in-person, mixed-mode"}, {"id": "228c1671-8538-4419-928d-876c2796182f", "type": "concept", "title": "Cross-sectional and repeated surveys"}, {"id": "7094f596-2d2c-41f9-8340-6052bdf65409", "type": "concept", "title": "Response rates and coverage"}, {"id": "6fa8b1e1-2ccb-495a-a20d-9014f7beabe8", "type": "concept", "title": "Anonymous versus identifiable responses"}], "description": "Students learn when surveys are useful and how design choices shape answers."}, {"id": "b4d13353-e700-4eb1-9faa-1a5f522ecaf8", "type": "subtopic", "title": "Questionnaire construction", "children": [{"id": "12be6b6d-7f3a-4afd-a486-bfcc8b848b20", "type": "concept", "title": "Question wording and reading level"}, {"id": "2c911f51-fb92-4136-8f0a-37dfe8994f5d", "type": "concept", "title": "Response scales and skip logic"}, {"id": "677df34b-3dcf-406c-950d-7939e9e161dc", "type": "concept", "title": "Sensitive questions and social desirability"}, {"id": "933b5c8f-272b-4118-a118-49388df95719", "type": "concept", "title": "Pilot testing and cognitive interviewing"}], "description": "This subtopic teaches clear, ethical, and analyzable question writing."}, {"id": "78455fec-b829-443b-9e82-c01e3631d2ac", "type": "subtopic", "title": "Other instruments and agency data forms", "children": [{"id": "3f9dcec4-38c3-48ee-b2eb-299d38592bd8", "type": "concept", "title": "Screeners and assessment tools"}, {"id": "c2ee6dbd-7486-4300-9288-8ad84fd581ad", "type": "concept", "title": "Observation checklists"}, {"id": "1e817514-cb58-4d96-8681-77f8f0df2ada", "type": "concept", "title": "Interview and focus-group guides"}, {"id": "540e9ac8-ae6c-42a5-ae6f-ddbaa2b6e8eb", "type": "concept", "title": "Service-use and case-management records"}], "description": "Students broaden instrument design beyond surveys."}]}, {"id": "ad3b08e1-f0a0-42df-979f-10045c7ee953", "type": "topic", "title": "Quantitative Data Analysis, Statistics, and Data Visualization for Social Work", "description": "This topic builds practical fluency in describing, comparing, visualizing, and interpreting social work data.", "children": [{"id": "75f57c2a-eb83-412f-b61c-f903253f00fd", "type": "subtopic", "title": "Descriptive analysis", "children": [{"id": "568d1979-ced2-459e-b5a2-9b79c8e35048", "type": "concept", "title": "Frequencies, percentages, rates, means, medians, and variation"}, {"id": "d0b515cd-9582-41d7-877a-593614c2a1bc", "type": "concept", "title": "Cross-tabulations and subgroup comparisons"}, {"id": "8eed6f0f-9ea3-4738-8af9-f842dcf40b6f", "type": "concept", "title": "Missing data and outliers"}, {"id": "dd1a2492-c5ae-4395-a29f-2d659ae1c318", "type": "concept", "title": "Data dictionaries and codebooks"}], "description": "Students learn to summarize data in ways that are accurate, useful, and readable."}, {"id": "0a8f2255-474b-4be7-b829-a21645677b36", "type": "subtopic", "title": "Inference and association", "children": [{"id": "a0763a79-08df-4feb-9d5c-5a94b73ce9a0", "type": "concept", "title": "Confidence intervals and uncertainty"}, {"id": "97237a21-fdfa-4001-8d0a-c3296db4d711", "type": "concept", "title": "Hypothesis tests and p-values"}, {"id": "276ec95b-1131-42e2-ade1-b761a3e54e4e", "type": "concept", "title": "Correlation and regression basics"}, {"id": "eeaaacbd-6baa-496f-b045-895632a32952", "type": "concept", "title": "Effect size and practical significance"}], "description": "This subtopic introduces statistical reasoning without letting formulas replace interpretation."}, {"id": "75ca74b2-d65f-4277-8be4-f435af0f66b8", "type": "subtopic", "title": "Visualization and interpretation", "children": [{"id": "bebb3a17-554b-4dc0-b565-07000217e98c", "type": "concept", "title": "Bar charts, line charts, scatterplots, dashboards, and maps"}, {"id": "f7d47937-5d21-4a15-87da-e1e824414d0b", "type": "concept", "title": "Clear labels and accessibility"}, {"id": "8dd34566-01e4-4734-82d4-6ae40f0f2fd9", "type": "concept", "title": "Avoiding misleading charts"}, {"id": "4ce7f196-8df7-49ff-8d52-3108bc2dadfa", "type": "concept", "title": "Equity-aware disaggregation"}], "description": "Students practice communicating patterns without distortion."}]}, {"id": "979bfbad-e458-4fd4-8100-e4e786079286", "type": "topic", "title": "Qualitative Methods: Interviews, Focus Groups, Observation, and Fieldnotes", "description": "Students learn how qualitative methods capture meaning, experience, context, relationships, and systems.", "children": [{"id": "86ea4b47-2fa2-4fc9-a452-ea847b273a46", "type": "subtopic", "title": "Qualitative interviewing", "children": [{"id": "8f344533-be21-48a6-a4d7-768a63a01319", "type": "concept", "title": "Structured, semi-structured, and unstructured interviews"}, {"id": "df37440b-e642-471c-a1a3-7163c4c809ff", "type": "concept", "title": "Interview guides and probes"}, {"id": "4c8ade79-fe18-4c17-b78a-fe2c9d30a3cb", "type": "concept", "title": "Rapport and power"}, {"id": "f11459b4-a26c-4163-b087-883f6d34e0ae", "type": "concept", "title": "Recording, transcription, and confidentiality"}], "description": "Students learn how interviews capture meaning, story, identity, relationship, and institutional experience."}, {"id": "13580aa2-4e56-46ae-bf1d-8ac81cb32a41", "type": "subtopic", "title": "Focus groups and group methods", "children": [{"id": "700f3522-f8ca-4a25-abfe-37a76898bc55", "type": "concept", "title": "Group composition and facilitation"}, {"id": "151ff78f-3d07-4d22-aedc-b78d471888a9", "type": "concept", "title": "Managing dominant voices and sensitive topics"}, {"id": "d6f6c72a-3a07-48be-aaa9-93646d6a61d6", "type": "concept", "title": "Consensus and conflict as data"}, {"id": "a63fcdbe-93ec-41f8-9463-dbfecaf2ac8c", "type": "concept", "title": "Virtual and in-person considerations"}], "description": "Focus groups reveal shared meanings, disagreement, norms, and interaction."}, {"id": "bf331ad8-3efd-451e-acff-d70af6eea241", "type": "subtopic", "title": "Observation and fieldnotes", "children": [{"id": "6115467e-13ac-4047-b9bf-766acd4d5f3b", "type": "concept", "title": "Participant and nonparticipant observation"}, {"id": "98762f45-d412-4d54-b2f2-b793638ef614", "type": "concept", "title": "Jottings, expanded notes, and analytic memos"}, {"id": "e928235b-9cd9-41eb-b91f-309f5b298383", "type": "concept", "title": "Researcher role and reactivity"}, {"id": "336643ce-b5fb-49df-8d40-d6fe6126bbc3", "type": "concept", "title": "Safety and boundaries in the field"}], "description": "Students learn to document practice settings, community spaces, interactions, and processes."}]}, {"id": "435f7970-cc6a-4e07-971c-fa67db0f1a3d", "type": "topic", "title": "Qualitative Coding, Thematic Analysis, Trustworthiness, and Reflexivity", "description": "This topic develops disciplined qualitative analysis and reflexive interpretation.", "children": [{"id": "b06285df-ef1c-47fe-af9b-08d877911a83", "type": "subtopic", "title": "Coding and theme development", "children": [{"id": "a51cfc8b-d379-4d97-a48b-db3eec99b261", "type": "concept", "title": "Open, focused, axial, and thematic coding"}, {"id": "09b1e0ec-95d2-44ee-8388-75bef9bb0212", "type": "concept", "title": "Codebooks and coding teams"}, {"id": "0a200de9-31c0-4973-a974-fc8d0e390a72", "type": "concept", "title": "Matrices and memoing"}, {"id": "4754a40f-174c-46ac-8f10-71c182b23afa", "type": "concept", "title": "Negative cases and deviant examples"}], "description": "Students learn how qualitative analysis moves from raw text to credible interpretation."}, {"id": "643b857b-3dce-405c-a750-e6a10e0fe7be", "type": "subtopic", "title": "Trustworthiness", "children": [{"id": "6ab57a80-345d-4d3f-a64f-922d111d26ac", "type": "concept", "title": "Credibility, transferability, dependability, and confirmability"}, {"id": "891e2a2f-73b7-4b44-a6df-30f3d17e26f1", "type": "concept", "title": "Member reflection and peer debriefing"}, {"id": "a29557ac-0a99-4da4-800d-7dcc68236a82", "type": "concept", "title": "Audit trails and thick description"}, {"id": "5d978962-29e5-401b-bbdf-e88fcb9bfcbc", "type": "concept", "title": "Triangulation and saturation"}], "description": "This subtopic teaches how qualitative studies earn confidence."}, {"id": "54e41003-251a-437d-8e9e-ae2aea5f7aa4", "type": "subtopic", "title": "Reflexivity and positionality", "children": [{"id": "f7f6456b-6d74-4fb0-8c75-ea2544b9e3e0", "type": "concept", "title": "Positionality statements"}, {"id": "0ca54a2e-3e42-4591-85fe-a6c30ad3f1e8", "type": "concept", "title": "Insider and outsider roles"}, {"id": "9a786040-868d-4989-bb3d-cd0e0aae4b9b", "type": "concept", "title": "Emotional labor and vicarious trauma"}, {"id": "d358fdc2-aa05-43b5-b6fc-444f4a805b3b", "type": "concept", "title": "Representation and voice"}], "description": "Students examine how researcher identity, power, assumptions, and relationships shape knowledge."}]}, {"id": "49935e09-0840-42e7-98f1-61793e715174", "type": "topic", "title": "Mixed Methods, Participatory Action Research, and Community-Engaged Inquiry", "description": "Students learn how multiple forms of evidence can be integrated with community participation and accountability.", "children": [{"id": "17525880-0e43-4f49-a204-cff27ee9d4a0", "type": "subtopic", "title": "Mixed-methods design", "children": [{"id": "5fe8a278-11ce-4c65-b3c0-c4c169eb4ec7", "type": "concept", "title": "Convergent, explanatory sequential, exploratory sequential, and embedded designs"}, {"id": "6dede643-a65d-4493-8472-ac586f482ab4", "type": "concept", "title": "Integration points"}, {"id": "7a4bd63e-1c5d-4b54-8de5-a6ce83c9ae0e", "type": "concept", "title": "Triangulation and contradiction"}, {"id": "a458fa75-1a35-430d-a8cf-1ca789064e50", "type": "concept", "title": "Design tradeoffs"}], "description": "Students learn how qualitative and quantitative evidence can answer complementary questions."}, {"id": "ec0d906e-c954-43ad-a083-69641d6081e7", "type": "subtopic", "title": "Participatory action research", "children": [{"id": "271cd712-f855-4a3e-b59c-47a9e1cca1b1", "type": "concept", "title": "Co-defining problems"}, {"id": "68ab9169-4c1c-451d-b971-b7c05f58ec74", "type": "concept", "title": "Community researchers and advisory boards"}, {"id": "85baac97-205f-4f6f-9111-8d9c46cfe0a6", "type": "concept", "title": "Action-reflection cycles"}, {"id": "4c31e461-1aae-49b9-9e43-b905c375c4f2", "type": "concept", "title": "Shared ownership of findings"}], "description": "This subtopic centers research as collaborative inquiry for change."}, {"id": "33edb48b-d8d3-4d9b-9648-5c5bab7c4564", "type": "subtopic", "title": "Community-engaged research practice", "children": [{"id": "bd33581c-58f2-4971-9cb9-160c8d9463ab", "type": "concept", "title": "Memoranda of understanding"}, {"id": "f4bbe5c7-adaf-458b-a74f-2e4ad98cb734", "type": "concept", "title": "Reciprocity and benefit sharing"}, {"id": "02bb6016-db26-4eb7-acee-46686a858d27", "type": "concept", "title": "Capacity building"}, {"id": "00f9a4dc-c83a-4996-9e77-b3818999ab43", "type": "concept", "title": "Accessible dissemination"}], "description": "Students learn to build respectful research relationships with agencies and communities."}]}, {"id": "64016277-85ec-48d3-befd-14e6a841c0bc", "type": "topic", "title": "Evidence-Based Practice, Critical Appraisal, and Evidence Synthesis", "description": "Students practice finding, appraising, and translating research evidence without treating evidence as detached from context.", "children": [{"id": "d830ccfa-67ad-47bd-9d2d-da49ed2102db", "type": "subtopic", "title": "Finding evidence", "children": [{"id": "655735d5-af15-423e-ac0f-626219490f10", "type": "concept", "title": "Practice questions and search strategies"}, {"id": "e4b4526c-3316-45b2-bef6-216d2870007f", "type": "concept", "title": "Social Work Abstracts, PubMed, Campbell, Cochrane, and agency evidence hubs"}, {"id": "c5a71103-ced0-4b84-a5e5-07abc25be0ab", "type": "concept", "title": "Grey literature and community reports"}, {"id": "e8e85db9-eb12-481f-bd6b-9d7c597b070c", "type": "concept", "title": "Citation management"}], "description": "Students learn how to search for relevant intervention, policy, and practice evidence."}, {"id": "e5351ab7-c516-4bf4-9423-8032c77d2951", "type": "subtopic", "title": "Critical appraisal", "children": [{"id": "df4c4564-6a40-48ea-b8a8-931bcc572760", "type": "concept", "title": "Study design and bias"}, {"id": "38950911-af1f-4c71-b6b1-52f78955ce52", "type": "concept", "title": "Sample, measures, and comparison groups"}, {"id": "c22ef6a8-ee53-4797-bd5d-6f609fbcd1c0", "type": "concept", "title": "Effect sizes and confidence"}, {"id": "3f1329f5-ae48-4421-a654-805629abc371", "type": "concept", "title": "Generalizability to client/community context"}], "description": "Students learn to judge evidence quality and relevance."}, {"id": "7c94d3a3-bce8-4161-b699-4c80f8c88b17", "type": "subtopic", "title": "Evidence synthesis and translation", "children": [{"id": "32e1cae8-167a-4d5b-b869-48882686e144", "type": "concept", "title": "Systematic reviews and meta-analyses"}, {"id": "9b5f26fd-e01b-41d7-904b-56cd49ddfab8", "type": "concept", "title": "Practice guidelines and evidence clearinghouses"}, {"id": "c5a02e6e-3bd5-440e-82d7-601a64a03e2f", "type": "concept", "title": "Implementation context"}, {"id": "14ece04e-0862-4666-8687-587ee3e1905b", "type": "concept", "title": "Equity and client preference in evidence use"}], "description": "The point is to use evidence thoughtfully rather than mechanically."}]}, {"id": "8541466c-d5d8-47be-923e-56cbceb65cd3", "type": "topic", "title": "Single-System Design, Practice Evaluation, and Outcome Monitoring", "description": "This topic teaches students to evaluate change in individual, family, group, and small-system practice.", "children": [{"id": "f70b5921-cb26-46e7-92ee-c76d4787939e", "type": "subtopic", "title": "Single-system design logic", "children": [{"id": "2dda5e96-098a-4d2c-a49a-c641fb9345ed", "type": "concept", "title": "Baseline and intervention phases"}, {"id": "354e9b56-95ea-46e7-bc9f-397efbb8eb1e", "type": "concept", "title": "A-B, A-B-A, A-B-A-B, and multiple-baseline designs"}, {"id": "664949c8-5ab6-4af3-8965-dd857aa02db2", "type": "concept", "title": "Repeated measurement"}, {"id": "989a4d1e-b48b-4116-83ed-d918998d5189", "type": "concept", "title": "Visual analysis"}], "description": "Students learn to evaluate change in direct practice with individuals, families, groups, and small systems."}, {"id": "28aaf8f2-0523-4212-a2c6-f7d4bffbe3c8", "type": "subtopic", "title": "Outcome monitoring in practice", "children": [{"id": "7f79e4f8-ce59-443e-b1cb-3f928b8270a4", "type": "concept", "title": "Goal attainment scaling"}, {"id": "594ef28c-91f7-4ac2-9c30-72fa02ff4349", "type": "concept", "title": "Progress monitoring"}, {"id": "d8112086-8355-4950-ade0-9e03a50359ca", "type": "concept", "title": "Client feedback tools"}, {"id": "ac069ea1-84ef-4816-9889-8896d2cc9383", "type": "concept", "title": "Documenting meaningful change"}], "description": "This subtopic connects research methods to everyday casework and clinical accountability."}, {"id": "7545dfb5-441b-48c5-90a3-5def1fb13501", "type": "subtopic", "title": "Threats and ethics in practice evaluation", "children": [{"id": "c3199228-8684-4d78-a475-53297029eade", "type": "concept", "title": "Maturation, history, regression, and measurement effects"}, {"id": "43a72a80-4030-45a3-9eeb-8048aba8a488", "type": "concept", "title": "Burden of repeated measurement"}, {"id": "e8b6d9f9-c38e-479c-8555-95394e087f36", "type": "concept", "title": "Confidentiality in small caseloads"}, {"id": "333008c1-dc51-49d2-9766-00382f141e74", "type": "concept", "title": "Using data without blaming clients"}], "description": "Students learn to interpret change cautiously and ethically."}]}, {"id": "cf9e7753-683e-4d08-9d6f-89073940bc3b", "type": "topic", "title": "Program Evaluation, Logic Models, and Theories of Change", "description": "Students learn how to assess programs, services, interventions, and organizational change efforts.", "children": [{"id": "2091bce7-7634-42aa-8920-ea273c28dbc1", "type": "subtopic", "title": "Logic models and theories of change", "children": [{"id": "e9fb7981-5bac-4045-9728-c37e82ed273c", "type": "concept", "title": "Inputs, activities, outputs, outcomes, and impact"}, {"id": "90dfa819-91ea-4b39-ab03-e2008c870d3d", "type": "concept", "title": "Assumptions and external factors"}, {"id": "d5a6cfb3-eb92-4b11-ade8-0a02e46043ee", "type": "concept", "title": "Short-, medium-, and long-term outcomes"}, {"id": "2cf5eb12-9edb-42ce-ad35-764a3bbcef56", "type": "concept", "title": "Equity-centered theory of change"}], "description": "Students learn to describe how a program is supposed to work before judging whether it works."}, {"id": "2350ae23-df8e-4639-99e5-5a299b7d5812", "type": "subtopic", "title": "Evaluation types", "children": [{"id": "8a77e929-a96d-440a-9dbf-b6e02cda39f7", "type": "concept", "title": "Needs assessment"}, {"id": "de964c81-6433-4a8c-b8ca-b764dbf9e4a0", "type": "concept", "title": "Process and implementation evaluation"}, {"id": "defa8c19-f0c8-41bd-9f23-791cf5e77140", "type": "concept", "title": "Outcome and impact evaluation"}, {"id": "67c44823-0c2e-4f5e-bcc7-df3610f741be", "type": "concept", "title": "Cost, efficiency, and performance measurement"}], "description": "Different evaluation questions require different designs and evidence."}, {"id": "e9274b10-3789-445d-85c0-f3c1616d55e0", "type": "subtopic", "title": "Participatory and utilization-focused evaluation", "children": [{"id": "5fea2ddd-d96f-442e-af68-4a3cc0e82843", "type": "concept", "title": "Stakeholder mapping"}, {"id": "bb79d530-74f2-49fd-91f8-a8d4956ffc4e", "type": "concept", "title": "Evaluation questions and decision use"}, {"id": "c529ffe9-b00e-4165-b4e4-925d79446547", "type": "concept", "title": "Reporting formats for different audiences"}, {"id": "780c5d33-b281-40f5-b51f-228f319b8b96", "type": "concept", "title": "Using findings for improvement"}], "description": "Evaluation is strongest when it is useful to people making decisions."}]}, {"id": "d3d0bd92-3453-41e8-aeea-7d3982961d8f", "type": "topic", "title": "Research Communication, Data Storytelling, Dissemination, and Policy Translation", "description": "Students learn to communicate findings clearly to clients, agencies, funders, communities, policymakers, and scholarly audiences.", "children": [{"id": "1f68a990-0f49-4089-b0d1-834e1a91eb88", "type": "subtopic", "title": "Writing research findings", "children": [{"id": "8ef50695-a7a6-49db-89e4-1d940eab5f0f", "type": "concept", "title": "Methods sections"}, {"id": "b52cfe80-3a76-4970-a6c2-9799a061c783", "type": "concept", "title": "Findings/results sections"}, {"id": "f6eb8dc8-d957-463f-9b87-f668337a9d2f", "type": "concept", "title": "Limitations and positionality"}, {"id": "cb294d96-ab25-470a-ac2c-078036f87f74", "type": "concept", "title": "Appendices, tables, and figures"}], "description": "Students learn to write methods and findings clearly enough for critique, replication, and use."}, {"id": "2d22ee8c-1c6f-478b-ba28-0617d18a4643", "type": "subtopic", "title": "Data storytelling", "children": [{"id": "7aa6a2e4-7e67-4c0a-8651-d0cf1398f71f", "type": "concept", "title": "Audience, message, and action"}, {"id": "2db36636-4199-4a97-9738-f6dbf968a1d8", "type": "concept", "title": "Plain-language summaries"}, {"id": "25424b49-4431-4cf0-adc4-ae95eddb9e2c", "type": "concept", "title": "Visual displays and dashboards"}, {"id": "11181754-5403-45cc-999f-c7569a8d44df", "type": "concept", "title": "Avoiding overclaiming"}], "description": "The goal is to make evidence understandable without oversimplifying it."}, {"id": "7083c2a6-d826-4228-be88-82c9c7032ebc", "type": "subtopic", "title": "Dissemination and policy translation", "children": [{"id": "63f05f17-e7d6-4781-ac8e-6fd063f7f113", "type": "concept", "title": "Agency briefs and executive summaries"}, {"id": "e7209f44-a376-4564-ba91-b1efe9ed936b", "type": "concept", "title": "Community presentations"}, {"id": "61c19521-78ae-496e-8d12-a53dca942da2", "type": "concept", "title": "Policy memos and testimony"}, {"id": "8086e335-6821-4fcd-8335-77e94fbe8e93", "type": "concept", "title": "Scholarly posters and conference talks"}], "description": "Students learn how research can influence practice, programs, advocacy, and policy."}]}, {"id": "2c4614d6-a01c-4fad-8356-b5d5d86e7a53", "type": "topic", "title": "Applied Social Work Research Proposal and Evaluation Capstone", "description": "The course culminates in a rigorous applied research or evaluation proposal that integrates question, design, ethics, evidence, data collection, analysis, and dissemination.", "children": [{"id": "ece013b9-ec77-4e68-b8b1-0f5921674003", "type": "subtopic", "title": "Proposal architecture", "children": [{"id": "0df3bf21-9077-46b7-9113-e57f5c348c31", "type": "concept", "title": "Problem statement and significance"}, {"id": "ee2590f4-63c9-44a7-bbc7-1417dd4d49aa", "type": "concept", "title": "Research or evaluation questions"}, {"id": "7dab1553-aec2-4ed8-8c53-eea2d5bed71a", "type": "concept", "title": "Literature and conceptual framework"}, {"id": "c4e328b0-df8f-4103-bd31-8368cde06dde", "type": "concept", "title": "Design, sample, measures, data collection, and analysis"}], "description": "Students synthesize the full course into a coherent applied study."}, {"id": "df858cee-a760-4d29-b65f-432cb014343a", "type": "subtopic", "title": "Ethics and feasibility", "children": [{"id": "e2b54ef3-8a94-431f-a6a4-242bb400d060", "type": "concept", "title": "IRB considerations"}, {"id": "4d64d332-48ef-4abd-9739-b040a21a16c6", "type": "concept", "title": "Recruitment and access"}, {"id": "13ccc1e6-6451-4d17-9c45-3754d6717c30", "type": "concept", "title": "Timeline and resources"}, {"id": "0f47697a-e851-469e-b578-fae0f4e23938", "type": "concept", "title": "Risk mitigation and data protection"}], "description": "A strong proposal is ambitious but doable and ethically defensible."}, {"id": "61b3b7a6-bb17-4ddd-989f-f9489cfce166", "type": "subtopic", "title": "Capstone presentation and revision", "children": [{"id": "37d663af-9a30-47db-8e1b-4d24a4248c4e", "type": "concept", "title": "Peer critique"}, {"id": "d2a87f7a-5710-4067-a334-ef70f9ec52b3", "type": "concept", "title": "Stakeholder"}, {"id": "bff4d4e6-7001-4262-918a-946cc7bd5ca5", "type": "concept", "title": "Revision memo"}, {"id": "f3fb3cbd-f161-4c29-9d68-b4d54fd35740", "type": "concept", "title": "Final proposal or evaluation plan"}], "description": "Students learn that research design improves through feedback."}]}], "dbBacked": true}$rmswjson$::jsonb,
